 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row) - {bg}

    # Extend diagonal rays of repeated marker colors. Color 5 is part of the
    # fixed starting motif in the first example, not one of the rays.
    for color in colors - {5}:
        cells = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color}
        for dr, dc in ((1, 1), (1, -1)):
            # Find maximal same-color diagonal runs; extend each run at both ends.
            for r, c in list(cells):
                if (r - dr, c - dc) in cells:
                    continue
                run = [(r, c)]
                rr, cc = r + dr, c + dc
                while (rr, cc) in cells:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                # Extend before and after the run through background cells to edges/obstacles.
                rr, cc = run[0]
                while 0 <= rr - dr < h and 0 <= cc - dc < w and grid[rr - dr][cc - dc] == bg:
                    rr -= dr
                    cc -= dc
                    out[rr][cc] = color
                rr, cc = run[-1]
                while 0 <= rr + dr < h and 0 <= cc + dc < w and grid[rr + dr][cc + dc] == bg:
                    rr += dr
                    cc += dc
                    out[rr][cc] = color
    return out
